private val penColors=listOf(0xFF111111,0xFF1D4ED8,0xFFB91C1C,0xFF15803D)
@Composable fun NotebookScreen(){val dao=EncyclopaediaDatabase.get(LocalContext.current).dao();val scope=rememberCoroutineScope();val pages by dao.observeNotebookPages().collectAsStateWithLifecycle(emptyList());var title by remember{mutableStateOf("")};var pageToDelete by remember{mutableStateOf<NotebookPageEntity?>(null)};var selectedPageId by remember{mutableStateOf<String?>(null)};var renamePage by remember{mutableStateOf<NotebookPageEntity?>(null)};var renameText by remember{mutableStateOf("")};pageToDelete?.let{p->AlertDialog(onDismissRequest={pageToDelete=null},title={Text("Delete notebook page?")},text={Text("${p.title} and every layer and handwritten stroke on it will be permanently deleted.")},confirmButton={TextButton(onClick={pageToDelete=null;scope.launch(Dispatchers.IO){dao.deleteNotebookPage(p.id)}}){Text("Delete")}},dismissButton={TextButton(onClick={pageToDelete=null}){Text("Cancel")}})};renamePage?.let{p->AlertDialog(onDismissRequest={renamePage=null},title={Text("Rename page")},text={OutlinedTextField(renameText,{renameText=it.take(100)},singleLine=true,label={Text("Page title")})},confirmButton={TextButton(enabled=renameText.isNotBlank(),onClick={val n=renameText.trim();renamePage=null;scope.launch(Dispatchers.IO){dao.renameNotebookPage(p.id,n)}}){Text("Save")}},dismissButton={TextButton(onClick={renamePage=null}){Text("Cancel")}})};val p=pages.firstOrNull{it.id==selectedPageId};if(p!=null){NotebookPageCanvas(p){selectedPageId=null};return};LazyColumn(Modifier.fillMaxSize().padding(28.dp),verticalArrangement=Arrangement.spacedBy(14.dp)){item{Text("Notebook",style=MaterialTheme.typography.headlineMedium);Text("Handwritten study pages are stored locally and included in your backups.",color=MaterialTheme.colorScheme.onSurfaceVariant)};item{Card(Modifier.fillMaxWidth()){Column(Modifier.padding(16.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){Text("New page",style=MaterialTheme.typography.titleMedium);OutlinedTextField(title,{title=it.take(100)},label={Text("Page title")},modifier=Modifier.fillMaxWidth(),singleLine=true);Button(enabled=title.isNotBlank(),onClick={val t=title.trim();title="";scope.launch(Dispatchers.IO){val id=UUID.randomUUID().toString();dao.upsertNotebookPage(NotebookPageEntity(id=id,title=t));dao.upsertNotebookLayer(NotebookLayerEntity(id=UUID.randomUUID().toString(),pageId=id,name="Writing"))}}){Text("Create page")}}}};if(pages.isEmpty())item{Text("No notebook pages yet. Create one above to start writing.")}else items(pages,key={it.id}){page->Card(Modifier.fillMaxWidth().clickable{selectedPageId=page.id}){Row(Modifier.fillMaxWidth().padding(16.dp),horizontalArrangement=Arrangement.SpaceBetween){Column(Modifier.weight(1f)){Text(page.title,style=MaterialTheme.typography.titleMedium);Text(page.background.lowercase().replaceFirstChar{it.uppercase()}+" page",color=MaterialTheme.colorScheme.onSurfaceVariant)};Row{TextButton(onClick={renameText=page.title;renamePage=page}){Text("Rename")};TextButton(onClick={pageToDelete=page}){Text("Delete",color=MaterialTheme.colorScheme.error)}}}}}}}
@Composable private fun NotebookPageCanvas(page:NotebookPageEntity,onBack:()->Unit){val context=LocalContext.current;val dao=EncyclopaediaDatabase.get(context).dao();val prefs=remember(context){NotebookPreferences(context)};val scope=rememberCoroutineScope();val layers by dao.observeNotebookLayers(page.id).collectAsStateWithLifecycle(emptyList());val pageStrokes by dao.observeNotebookPageStrokes(page.id).collectAsStateWithLifecycle(emptyList());var selectedLayerId by remember{mutableStateOf<String?>(null)};val selectedLayer=layers.firstOrNull{it.id==selectedLayerId}?:layers.firstOrNull{it.isVisible&&!it.isLocked};val writableLayer=selectedLayer?.takeIf{it.isVisible&&!it.isLocked};var palm by remember{mutableStateOf(prefs.palmRejection)};var tool by remember{mutableStateOf(NotebookTool.PEN)};var penWidth by remember{mutableStateOf(prefs.penWidth)};var penColor by remember{mutableStateOf(prefs.penColorArgb)};var selectedStrokeIds by remember{mutableStateOf<Set<String>>(emptySet())};var newLayer by remember{mutableStateOf("")};var showLayers by remember{mutableStateOf(false)};val background=runCatching{NotebookBackground.valueOf(page.background)}.getOrDefault(NotebookBackground.PLAIN);val undo=remember{mutableStateListOf<NotebookHistoryAction>()};val redo=remember{mutableStateListOf<NotebookHistoryAction>()};val visibleIds=remember(layers){layers.filter{it.isVisible}.map{it.id}.toSet()};val decoded=remember(pageStrokes){pageStrokes.mapNotNull{e->decodeStroke(e)?.let{e to it}}};val canvas=remember(decoded,visibleIds){decoded.filter{it.first.layerId in visibleIds}.map{it.second}};val selected=remember(decoded,selectedLayer?.id){decoded.filter{it.first.layerId==selectedLayer?.id}};val selectedCanvas=selected.filter{it.first.id in selectedStrokeIds}.map{it.second};fun transformSelected(dx:Float=0f,dy:Float=0f,scale:Float=1f){val chosen=selected.filter{it.first.id in selectedStrokeIds};if(chosen.isEmpty())return;val pts=chosen.flatMap{it.second.points};val cx=pts.map{it.x}.average().toFloat();val cy=pts.map{it.y}.average().toFloat();scope.launch(Dispatchers.IO){chosen.forEach{(e,s)->val np=s.points.map{p->Offset(cx+(p.x-cx)*scale+dx,cy+(p.y-cy)*scale+dy)};dao.upsertNotebookStroke(e.copy(pointsJson=encodePoints(s.copy(points=np)),width=e.width*scale))}}};fun duplicateSelected(){val chosen=selected.filter{it.first.id in selectedStrokeIds};if(chosen.isEmpty())return;val ids=mutableSetOf<String>();scope.launch(Dispatchers.IO){chosen.forEach{(e,s)->val id=UUID.randomUUID().toString();ids+=id;val moved=s.copy(points=s.points.map{it+Offset(28f,28f)});dao.upsertNotebookStroke(e.copy(id=id,pointsJson=encodePoints(moved)));undo.add(NotebookHistoryAction(e.copy(id=id,pointsJson=encodePoints(moved)),true))};selectedStrokeIds=ids};redo.clear()};fun deleteSelected(){val chosen=selected.filter{it.first.id in selectedStrokeIds};if(chosen.isEmpty())return;selectedStrokeIds=emptySet();redo.clear();chosen.forEach{(e,_)->undo.add(NotebookHistoryAction(e,false))};scope.launch(Dispatchers.IO){chosen.forEach{(e,_)->dao.deleteNotebookStroke(e.id)}}};Column(Modifier.fillMaxSize().padding(horizontal=16.dp,vertical=10.dp),verticalArrangement=Arrangement.spacedBy(6.dp)){Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Row{TextButton(onClick=onBack){Text("← Pages")};Text(page.title,style=MaterialTheme.typography.titleLarge,modifier=Modifier.padding(top=10.dp))};Row{TextButton(onClick={showLayers=!showLayers}){Text(if(showLayers)"Hide layers" else "Layers (${layers.size})")};Text("Palm",modifier=Modifier.padding(top=12.dp));Switch(palm,{palm=it;prefs.palmRejection=it})}};Row(Modifier.fillMaxWidth().horizontalScroll(rememberScrollState()),horizontalArrangement=Arrangement.spacedBy(6.dp)){listOf(NotebookTool.PEN to "Pen",NotebookTool.HIGHLIGHTER to "Highlighter",NotebookTool.ERASER to "Eraser",NotebookTool.LASSO to "Lasso").forEach{(t,n)->FilterChip(tool==t,{tool=t;if(t!=NotebookTool.LASSO)selectedStrokeIds=emptySet()},label={Text(n)})};listOf(2.5f,4f,7f).forEach{w->FilterChip(penWidth==w,{penWidth=w;prefs.penWidth=w},label={Text(if(w<3)"Fine" else if(w<6)"Medium" else "Bold")})};penColors.forEachIndexed{i,c->FilterChip(penColor==c,{penColor=c;prefs.penColorArgb=c},label={Text(listOf("Black","Blue","Red","Green")[i])})};OutlinedButton(enabled=undo.isNotEmpty(),onClick={val a=undo.removeLastOrNull()?:return@OutlinedButton;redo.add(a);scope.launch(Dispatchers.IO){if(a.added)dao.deleteNotebookStroke(a.stroke.id)else dao.upsertNotebookStroke(a.stroke)}}){Text("Undo")};OutlinedButton(enabled=redo.isNotEmpty(),onClick={val a=redo.removeLastOrNull()?:return@OutlinedButton;undo.add(a);scope.launch(Dispatchers.IO){if(a.added)dao.upsertNotebookStroke(a.stroke)else dao.deleteNotebookStroke(a.stroke.id)}}){Text("Redo")};NotebookBackground.entries.forEach{b->FilterChip(background==b,{scope.launch(Dispatchers.IO){dao.setNotebookPageBackground(page.id,b.name)}},label={Text(b.name.lowercase().replaceFirstChar{it.uppercase()})})}};if(selectedStrokeIds.isNotEmpty())Row(Modifier.fillMaxWidth().horizontalScroll(rememberScrollState()),horizontalArrangement=Arrangement.spacedBy(6.dp)){Text("${selectedStrokeIds.size} selected",modifier=Modifier.padding(top=10.dp));OutlinedButton(onClick={duplicateSelected()}){Text("Duplicate")};OutlinedButton(onClick={deleteSelected()}){Text("Delete")};TextButton(onClick={selectedStrokeIds=emptySet()}){Text("Deselect")}};if(showLayers)Card(Modifier.fillMaxWidth()){Column(Modifier.padding(10.dp)){layers.forEach{l->FilterChip(selectedLayer?.id==l.id,{selectedLayerId=l.id;selectedStrokeIds=emptySet()},label={Text(l.name)})};Row{OutlinedTextField(newLayer,{newLayer=it.take(40)},label={Text("New layer")},singleLine=true,modifier=Modifier.weight(1f));Button(enabled=newLayer.isNotBlank(),onClick={val n=newLayer.trim();newLayer="";val id=UUID.randomUUID().toString();scope.launch(Dispatchers.IO){dao.upsertNotebookLayer(NotebookLayerEntity(id=id,pageId=page.id,name=n,sortOrder=(layers.maxOfOrNull{it.sortOrder}?:-1)+1))};selectedLayerId=id}){Text("Add")}}}};Card(Modifier.fillMaxWidth().weight(1f)){NotebookCanvas(strokes=canvas,palmRejection=palm,selectedTool=tool,penWidth=penWidth,penColorArgb=penColor,background=background,onStrokeFinished={s->val l=writableLayer?:return@NotebookCanvas;val e=NotebookStrokeEntity(id=UUID.randomUUID().toString(),layerId=l.id,pointsJson=encodePoints(s),width=s.width,tool=s.tool.name,colorArgb=s.colorArgb);undo.add(NotebookHistoryAction(e,true));redo.clear();scope.launch(Dispatchers.IO){dao.upsertNotebookStroke(e)}},onEraseAt={p->val hit=selected.lastOrNull{(_,s)->s.isNear(p)}?.first;if(hit!=null){undo.add(NotebookHistoryAction(hit,false));redo.clear();scope.launch(Dispatchers.IO){dao.deleteNotebookStroke(hit.id)}}},onLassoFinished={poly->selectedStrokeIds=selected.filter{(_,s)->s.isInsidePolygon(poly)}.map{it.first.id}.toSet()},selectedStrokes=selectedCanvas,onSelectionMoved={d->transformSelected(dx=d.x,dy=d.y)},onSelectionScaled={scale->transformSelected(scale=scale)},modifier=Modifier.fillMaxSize())};if(tool==NotebookTool.LASSO)Text(if(selectedStrokeIds.isEmpty())"Draw around handwriting on the active layer to select it." else "Drag the box to move, use the blue handle to resize, or duplicate/delete the selection.",color=MaterialTheme.colorScheme.onSurfaceVariant)}}
private fun encodePoints(s:CanvasStroke)=JSONArray().apply{s.points.forEach{put(JSONObject().put("x",it.x.toDouble()).put("y",it.y.toDouble()))}}.toString()
private fun decodeStroke(e:NotebookStrokeEntity):CanvasStroke?=runCatching{val a=JSONArray(e.pointsJson);val p=(0 until a.length()).map{i->val o=a.getJSONObject(i);Offset(o.getDouble("x").toFloat(),o.getDouble("y").toFloat())};CanvasStroke(p,e.width,runCatching{NotebookTool.valueOf(e.tool)}.getOrDefault(NotebookTool.PEN),e.colorArgb)}.getOrNull()
